arguments.command:
cd /tmp/sv-3a3f67a839fb4850a211aa85ca42607b/symbols && readelf -sW libmonosgen-2.0.so.dbg | awk '
$2 ~ /^[0-9a-f]+$/ && $3+0 > 0 {
  addr = strtonum("0x" $2);
  size = $3+0;
  name = $NF;
  if (addr <= 0x2f4b20 && addr + size > 0x2f4b20) print "0x2f4b20 -> " name " (base: 0x" $2 ")";
  if (addr <= 0x2f4c84 && addr + size > 0x2f4c84) print "0x2f4c84 -> " name " (base: 0x" $2 ")";
}' 2>/dev/null | head -10

